LIBRARY_SPONSOR_MODEL = """
    CREATE RANGE INDEX IF NOT EXISTS FOR ()-[rel:HAS_VERSION]-() ON (rel.end_date);
    CREATE RANGE INDEX IF NOT EXISTS FOR ()-[rel:HAS_VERSION]-() ON (rel.start_date);
    CREATE TEXT INDEX IF NOT EXISTS FOR (n:Library) ON (n.name);
    CREATE CONSTRAINT constraint_DataModelIGValue_name IF NOT EXISTS FOR (node:DataModelIGValue) REQUIRE (node.name) IS NODE KEY;
    CREATE CONSTRAINT constraint_DataModelIGRoot_uid IF NOT EXISTS FOR (node:DataModelIGRoot) REQUIRE (node.uid) IS NODE KEY;
    CREATE CONSTRAINT UNIQUE_IMPORT_NAME IF NOT EXISTS FOR (node:`UNIQUE IMPORT LABEL`) REQUIRE (node.`UNIQUE IMPORT ID`) IS UNIQUE;
    UNWIND [{_id:1325814, properties:{name:"sdtmig_mastermodel_3.3_NN02"}}, {_id:1327770, properties:{name:"sdtmig_mastermodel_3.3_NN03"}}, {_id:1335750, properties:{name:"sdtmig_mastermodel_3.2_NN15"}}, {_id:1341902, properties:{name:"sdtmig_mastermodel_3.3_NN01"}}] AS row
    MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:SponsorModelValue;
    UNWIND [{_id:1290637, properties:{name:"Sponsor", is_editable:true}}] AS row
    MERGE (n:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row._id}) SET n += row.properties SET n:Library;
    UNWIND [{uid:"SDTMIG", properties:{}}] AS row
    MERGE (n:DataModelIGRoot{uid: row.uid}) SET n += row.properties;
    UNWIND [{name:"SDTMIG v3.2", properties:{effective_date:date('2013-11-26'), description:"CDISC Version 3.2 (V3.2) Study Data Tabulation Model Implementation Guide for Human Clinical Trials (SDTMIG) is intended to guide the organization, structure, and format of standard clinical trial tabulation datasets submitted to a regulatory authority such as the US Food and Drug Administration (FDA).", version_number:"3.2"}}, {name:"SDTMIG v3.3", properties:{effective_date:date('2018-11-20'), description:"CDISC Version 3.3 (v3.3) Study Data Tabulation Model Implementation Guide for Human Clinical Trials (SDTMIG) is intended to guide the organization, structure, and format of standard clinical trial tabulation datasets submitted to a regulatory authority.", version_number:"3.3"}}] AS row
    MERGE (n:DataModelIGValue{name: row.name}) SET n += row.properties;
    UNWIND [{start: {_id:1341902}, end: {name:"SDTMIG v3.3"}, properties:{}}, {start: {_id:1325814}, end: {name:"SDTMIG v3.3"}, properties:{}}, {start: {_id:1327770}, end: {name:"SDTMIG v3.3"}, properties:{}}, {start: {_id:1335750}, end: {name:"SDTMIG v3.2"}, properties:{}}] AS row
    MATCH (start:`UNIQUE IMPORT LABEL`{`UNIQUE IMPORT ID`: row.start._id})
    MATCH (end:DataModelIGValue{name: row.end.name})
    MERGE (start)-[r:EXTENDS_VERSION]->(end) SET r += row.properties;
    UNWIND [{start: {uid:"SDTMIG"}, end: {name:"SDTMIG v3.2"}, properties:{end_date:datetime('2018-11-20T00:00:00Z'), change_description:"New version imported", author_id:"CDISC_IMPORT", version:"3.2", status:"Final", start_date:datetime('2013-11-26T00:00:00Z')}}, {start: {uid:"SDTMIG"}, end: {name:"SDTMIG v3.3"}, properties:{end_date:datetime('2021-11-29T00:00:00Z'), change_description:"New version imported", author_id:"CDISC_IMPORT", version:"3.3", status:"Final", start_date:datetime('2018-11-20T00:00:00Z')}}] AS row
    MATCH (start:DataModelIGRoot{uid: row.start.uid})
    MATCH (end:DataModelIGValue{name: row.end.name})
    MERGE (start)-[r:HAS_VERSION]->(end) SET r += row.properties;
    MATCH (n:`UNIQUE IMPORT LABEL`)  WITH n LIMIT 20000 REMOVE n:`UNIQUE IMPORT LABEL` REMOVE n.`UNIQUE IMPORT ID`;
    DROP CONSTRAINT UNIQUE_IMPORT_NAME;
"""

