# Control Type as a single-select StudyTextField, one node per conversion branch:
# a value linked to a CT term (HAS_TYPE), a null flavor only, and a value with no
# term link. The first two are consecutive versions of one study with an audit
# trail entry between them; the third is a separate study, as a study version
# holds one Control Type field.
CONTROL_TYPE_STUDY_FIELDS = """
MERGE (sr:StudyRoot {uid: 'Study_CTRL_000001'})
CREATE (sv1:StudyValue {study_number: '9901', study_acronym: 'CTRL-1'})
CREATE (sv2:StudyValue {study_number: '9901', study_acronym: 'CTRL-1'})
MERGE (sr)-[:HAS_VERSION {status: 'Released', version: '1', start_date: datetime('2026-01-01T00:00:00.000Z'), end_date: datetime('2026-01-02T00:00:00.000Z')}]->(sv1)
MERGE (sr)-[:HAS_VERSION {status: 'Draft', version: '2', start_date: datetime('2026-01-02T00:00:00.000Z')}]->(sv2)
MERGE (sr)-[:LATEST]->(sv2)
MERGE (sr)-[:LATEST_DRAFT]->(sv2)

MERGE (ct_term:CTTermRoot {uid: 'CTRL_TEST_C49648'})
MERGE (nf_term:CTTermRoot {uid: 'CTRL_TEST_C48660'})

CREATE (valued:StudyField:StudyTextField {field_name: 'control_type_code', value: 'CTRL_TEST_C49648'})
CREATE (valued)-[:HAS_TYPE]->(:CTTermContext)-[:HAS_SELECTED_TERM]->(ct_term)
MERGE (sv1)-[:HAS_TEXT_FIELD]->(valued)

CREATE (null_flavored:StudyField:StudyTextField {field_name: 'control_type_code'})
CREATE (null_flavored)-[:HAS_REASON_FOR_NULL_VALUE]->(:CTTermContext)-[:HAS_SELECTED_TERM]->(nf_term)
MERGE (sv2)-[:HAS_TEXT_FIELD]->(null_flavored)

CREATE (sr)-[:AUDIT_TRAIL]->(action:StudyAction:Edit {date: datetime('2026-01-02T00:00:00.000Z'), author_id: 'unknown-user'})
CREATE (action)-[:BEFORE]->(valued)
CREATE (action)-[:AFTER]->(null_flavored)

MERGE (sr2:StudyRoot {uid: 'Study_CTRL_000002'})
CREATE (sv3:StudyValue {study_number: '9902', study_acronym: 'CTRL-2'})
MERGE (sr2)-[:HAS_VERSION {status: 'Draft', version: '1', start_date: datetime('2026-01-01T00:00:00.000Z')}]->(sv3)
MERGE (sr2)-[:LATEST]->(sv3)
MERGE (sr2)-[:LATEST_DRAFT]->(sv3)
CREATE (unlinked:StudyField:StudyTextField {field_name: 'control_type_code', value: 'CTRL_TEST_UNLINKED'})
MERGE (sv3)-[:HAS_TEXT_FIELD]->(unlinked)

MERGE (msf:MetaStudyField {osb_field_name: 'control_type_code'})
SET msf.osb_page_reference = '/study_properties/attributes'
CREATE (tsp:CTTermNameValue {name: 'Control Type', cardinality: 'One'})
CREATE (tsp)-[:RELATED_STUDY_FIELD_SELECTION]->(msf);
"""


# Semantic Data Type (SEMTCDT) codelist with the terms migrate_meta_study_fields links
# MetaStudyField nodes to. Without it the migration stops before changing any data.
# Synthetic data, shaped like the codelist the import_sponsor_data 'codelistterms2' step creates.
SEMANTIC_DATA_TYPE_CODELIST = """
MERGE (clr:CTCodelistRoot {uid: 'SEMTCDT_TEST_CODELIST'})
CREATE (clr)-[:HAS_ATTRIBUTES_ROOT]->(clar:CTCodelistAttributesRoot)
CREATE (clar)-[:LATEST]->(:CTCodelistAttributesValue {name: 'Semantic Data Type', submission_value: 'SEMTCDT', extensible: true})
WITH clr
UNWIND ['boolean', 'ctTerm', 'datetime', 'durationDatetime', 'integer', 'text'] AS sv
MERGE (ctr:CTTermRoot {uid: 'SEMTCDT_TEST_' + sv})
CREATE (clr)-[:HAS_TERM]->(:CTCodelistTerm {submission_value: sv})-[:HAS_TERM_ROOT]->(ctr);
"""


