# Remove a checkmark from the legacy SoA snapshot of the locked version,
# so that the SoA rendered from the legacy relationships differs from the SoA built from the study selections
LEGACY_SOA_SNAPSHOT_WITHOUT_A_CHECKMARK = """
MATCH (:StudyRoot {uid: 'Study_000001'})-[:HAS_VERSION {status: 'RELEASED', version: '1'}]->(:StudyValue)
    -[cell:HAS_PROTOCOL_SOA_CELL]->(:StudyActivitySchedule)
WITH cell
ORDER BY cell.row, cell.column
LIMIT 1
DELETE cell;
"""

# Legacy SoA snapshot relationship left over on the draft version
LEGACY_SOA_SNAPSHOT_ON_DRAFT = """
MATCH (:StudyRoot {uid: 'Study_000001'})-[:LATEST]->(study_value:StudyValue)-[:HAS_STUDY_ACTIVITY]->(study_activity:StudyActivity)
WITH study_value, study_activity
LIMIT 1
CREATE (study_value)-[:HAS_PROTOCOL_SOA_CELL {row: 0, column: 0, span: 1, is_propagated: false, order: 0}]->(study_activity);
"""

